for slug, data in stories.items():
    out_file = STORY_DIR / f"{slug}.md"
    fm = (
        "---\n"
        f"title: {json.dumps(data['title'])}\n"
        f"subtitle: {json.dumps(data['subtitle'])}\n"
        f"category: {json.dumps(data['category'])}\n"
        f"excerpt: {json.dumps(data['excerpt'])}\n"
        f"image: {json.dumps(data['image'])}\n"
        f"readingTime: {data['readingTime']}\n"
        f"pubDate: {data['pubDate']}\n"
        "---\n\n"
    )
    content = fm + data["body"]
    out_file.write_text(content, encoding="utf-8")
    print(f"Wrote real match story to {out_file}")

